async function boot(){try{const r=await call('catalogos');clients=r.clientes;products=r.productos;$('#cliente').replaceChildren(opt('','Selecciona un cliente'),...clients.map(c=>opt(c.idpersona,c.nombre+' · '+(c.num_documento||''))));$('#producto').replaceChildren(opt('','Selecciona un producto'),...products.map(p=>opt(p.idarticulo+':'+p.idvariacion,p.nombre+' · S/ '+Number(p.precio_venta).toFixed(2))));const preset=new URLSearchParams(location.search).get('cliente');if(preset && clients.some(c=>String(c.idpersona)===preset))$('#cliente').value=preset;await load()}catch(e){message(e.message,true)}}
async function load(){const id=$('#cliente').value;$('#rows').replaceChildren();if(!id)return;try{const r=await call('listarCliente&idcliente='+encodeURIComponent(id));agreements=r.data;for(const a of agreements){const product=products.find(p=>+p.idarticulo===+a.idarticulo && +p.idvariacion===+a.idvariacion);const tr=document.createElement('tr');const td=document.createElement('td');td.textContent=product?.nombre||'Producto '+a.idarticulo;const price=document.createElement('td');price.textContent='S/ '+Number(a.precio).toFixed(2);const act=document.createElement('td');const edit=document.createElement('button');edit.className='secondary';edit.textContent='Editar';edit.onclick=()=>{$('#producto').value=a.idarticulo+':'+a.idvariacion;$('#precio').value=a.precio;$('#precio').focus()};const del=document.createElement('button');del.className='danger';del.textContent='Eliminar';del.onclick=()=>remove(a);act.append(edit,' ',del);tr.append(td,price,act);$('#rows').append(tr)}if(!agreements.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent='Sin precios personalizados.';tr.append(td);$('#rows').append(tr)}}catch(e){message(e.message,true)}}
async function remove(a){if(!confirm('¿Desactivar el precio acordado?'))return;try{await call('eliminarCliente',{idcliente:$('#cliente').value,idarticulo:a.idarticulo,idvariacion:a.idvariacion});message('Precio desactivado.');load()}catch(e){message(e.message,true)}}
$('#save').onclick=async()=>{const [idarticulo,idvariacion]=($('#producto').value||'').split(':');const idcliente=$('#cliente').value,precio=$('#precio').value;if(!idcliente||!idarticulo||!(Number(precio)>0)){message('Selecciona cliente, producto y precio válido.',true);return}$('#save').disabled=true;try{await call('asignarCliente',{idcliente,idarticulo,idvariacion,precio});message('Precio personalizado guardado.');await load()}catch(e){message(e.message,true)}finally{$('#save').disabled=false}};
